        return False
    N, Q = int(t[0]), int(t[1])
    if not (1 <= N <= 2 * 10**5 and 1 <= Q <= 2 * 10**5):
        return False
    if len(t) != 2 + 3 * Q:
        return False
    for i in range(Q):
        L, R, C = int(t[2 + 3 * i]), int(t[3 + 3 * i]), int(t[4 + 3 * i])
        if not (1 <= L <= R <= N):
            return False
        if not (1 <= C <= 10**9):
            return False
    return True

