from itertools import combinations
from hypothesis import strategies as st


@st.composite
def gen(draw):
    N = draw(st.integers(1, 3))
    Q = draw(st.integers(1, 3))
    lines = [f"{N} {Q}"]
    for _ in range(Q):
        L = draw(st.integers(1, N))
        R = draw(st.integers(L, N))
        C = draw(st.one_of(st.integers(1, 10), st.integers(1, 10**9),
                           st.just(10**9), st.just(1)))
        lines.append(f"{L} {R} {C}")
    return "\n".join(lines) + "\n"


def validate(inp):
    t = inp.split()
    if len(t) < 2:
        return False
    N, Q = int(t[0]), int(t[1])
    if not (1 <= N <= 2 * 10**5 and 1 <= Q <= 2 * 10**5):
        return False
    if len(t) != 2 + 3 * Q:
        return False
    for i in range(Q):
        L, R, C = int(t[2 + 3 * i]), int(t[3 + 3 * i]), int(t[4 + 3 * i])
        if not (1 <= L <= R <= N):
            return False
        if not (1 <= C <= 10**9):
            return False
    return True


def ref(inp):
    # Brute force: enumerate every set of V-1 edges, keep those that
    # connect all V vertices (hence are spanning trees), take the minimum cost.
    t = list(map(int, inp.split()))
    N, Q = t[0], t[1]
    qs = [(t[2 + 3 * i], t[3 + 3 * i], t[4 + 3 * i]) for i in range(Q)]
    V = N + Q
    edges = []
    for i, (L, R, C) in enumerate(qs):
        for j in range(L, R + 1):
            edges.append((C, N + i + 1, j))
    best = None
    for comb in combinations(edges, V - 1):
        parent = list(range(V + 1))

        def find(x):
            while parent[x] != x:
                x = parent[x]
            return x

        comps = V
        for (c, a, b) in comb:
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb
                comps -= 1
        if comps == 1:
            cost = sum(c for (c, a, b) in comb)
            if best is None or cost < best:
                best = cost
    if best is None:
        return "-1"
    return str(best)
